const fs = require('fs');
const path = require('path');

const ROOT = __dirname;
const README_PATH = path.join(ROOT, 'README.md');
const INDEX_PATH = path.join(ROOT, 'INDEX.md');

const HEADING = /^#{1,6}\s+\S/;

function extractHeadings(markdown) {
  return markdown
    .split(/\r?\n/)
    .map((line) => line.trim())
    .filter((line) => HEADING.test(line));
}

function main() {
  const markdown = fs.readFileSync(README_PATH, 'utf8');
  const headings = extractHeadings(markdown);

  fs.writeFileSync(INDEX_PATH, headings.join('\n') + '\n', 'utf8');

  console.log(`Wrote ${headings.length} headings to ${path.relative(ROOT, INDEX_PATH)}`);
}

main();

